const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const fireLocation = ee.Geometry.Point([-116.45, 31.85]); // El Escondido area, Ensenada
  const oceanDirection = fireLocation.translate(50e3, 270); // 50 km west
  const plumeLine = ee.Geometry.LineString([fireLocation, oceanDirection]);
  const plumeBuffer = plumeLine.buffer(5e3); // 5 km buffer for plume detection
  const date = '2025-01-23';
  const timeWindow = ee.Date(date).advance(12, 'hour'); // ~1:44 pm local (21:44 UTC)

  // 2. Data Acquisition - MODIS Aqua for fire and smoke
  const fireCol = ee.ImageCollection('MODIS/061/MOD14A1')  // Terra active fire
    .filterBounds(fireLocation)
    .filterDate(date, ee.Date(date).advance(1, 'day'));
  const smokeCol = ee.ImageCollection('MODIS/061/MYD09GA')  // Aqua corrected reflectance
    .filterBounds(plumeBuffer)
    .filterDate(timeWindow, timeWindow.advance(3, 'hour'));

  // Check data availability
  const fireCount = fireCol.size().getInfo();
  const smokeCount = smokeCol.size().getInfo();
  console.log(`Fire hotspots: ${fireCount}, Smoke images: ${smokeCount}`);

  if (fireCount === 0 || smokeCount === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get fire pixel and latest smoke image
  const fireImg = fireCol.first();
  const smokeImg = smokeCol.sort('system:time_start', false).first();

  // Cloud masking for MODIS
  const cloudMask = smokeImg.select('state_1km').bitwiseAnd(1 << 0).eq(0);
  const maskedImg = smokeImg.updateMask(cloudMask).select(['sur_refl_b01', 'sur_refl_b03', 'sur_refl_b04']);

  // 4. Smoke detection using visible band thresholds
  const blue = maskedImg.select('sur_refl_b03').divide(10000); // Scale reflectance
  const red = maskedImg.select('sur_refl_b01').divide(10000);
  const smokeIndex = blue.subtract(red).divide(blue.add(red)).rename('smoke_idx');
  const smokeMask = smokeIndex.gt(-0.1).and(smokeIndex.lt(0.1)).and(blue.gt(0.15));

  // Count valid smoke pixels in plume buffer
  const stats = smokeMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: plumeBuffer,
    scale: 1000,
    maxPixels: 1e9,
  });
  const smokePixels = stats.get('smoke_idx').getInfo();
  console.log(`Smoke pixels in 50km buffer: ${smokePixels}`);

  // 5. Validation & Final Answer
  if (smokePixels === null || smokePixels === undefined) {
    console.log('<answer>C3</answer>');
  } else if (smokePixels === 0) {
    console.log('<answer>A</answer>'); // No smoke detected → extends <50 km
  } else {
    console.log('<answer>B</answer>'); // Smoke detected → extends ≥50 km
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
